			ErrPromptTooLong, embeds.Rows-lay.PrefixLen+lay.PrefixLen-condRowsOf(lay), condRowsOf(lay),
			p.maxPrefix, EditPrompt, p.refs)
	}
''')
open(p,'w').write(s)
